use std::collections::BTreeMap;
use std::io::Read;

enum V {
    Null,
    Bool,
    Int(f64),
    Num(f64),
    Str(String),
    Arr(Vec<V>),
    Obj(Vec<(String, V)>),
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn lit(&mut self, s: &str, v: V) -> Option<V> {
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            Some(v)
        } else {
            None
        }
    }
    fn value(&mut self, depth: usize) -> Option<V> {
        if depth > 200 {
            return None;
        }
        self.ws();
        let c = *self.b.get(self.i)?;
        match c {
            b'n' => self.lit("null", V::Null),
            b't' => self.lit("true", V::Bool),
            b'f' => self.lit("false", V::Bool),
            b'"' => Some(V::Str(self.string()?)),
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.b.get(self.i) == Some(&b']') {
                    self.i += 1;
                    return Some(V::Arr(v));
                }
                loop {
                    v.push(self.value(depth + 1)?);
                    self.ws();
                    match self.b.get(self.i)? {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            return Some(V::Arr(v));
                        }
                        _ => return None,
                    }
                }
            }
            b'{' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.b.get(self.i) == Some(&b'}') {
                    self.i += 1;
                    return Some(V::Obj(v));
                }
                loop {
                    self.ws();
                    if self.b.get(self.i)? != &b'"' {
                        return None;
                    }
                    let k = self.string()?;
                    self.ws();
                    if self.b.get(self.i)? != &b':' {
                        return None;
                    }
                    self.i += 1;
                    let val = self.value(depth + 1)?;
                    v.push((k, val));
                    self.ws();
                    match self.b.get(self.i)? {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Some(V::Obj(v));
                        }
                        _ => return None,
                    }
                }
            }
            b'-' | b'0'..=b'9' => self.number(),
            _ => None,
        }
    }
    fn digits(&mut self) -> usize {
        let s = self.i;
        while self.i < self.b.len() && self.b[self.i].is_ascii_digit() {
            self.i += 1;
        }
        self.i - s
    }
    fn number(&mut self) -> Option<V> {
        let s = self.i;
        if self.b[self.i] == b'-' {
            self.i += 1;
        }
        match self.b.get(self.i)? {
            b'0' => self.i += 1,
            b'1'..=b'9' => {
                self.digits();
            }
            _ => return None,
        }
        let mut int = true;
        if self.b.get(self.i) == Some(&b'.') {
            int = false;
            self.i += 1;
            if self.digits() == 0 {
                return None;
            }
        }
        if matches!(self.b.get(self.i), Some(b'e') | Some(b'E')) {
            int = false;
            self.i += 1;
            if matches!(self.b.get(self.i), Some(b'+') | Some(b'-')) {
                self.i += 1;
            }
            if self.digits() == 0 {
                return None;
            }
        }
        let t = std::str::from_utf8(&self.b[s..self.i]).ok()?;
        let f: f64 = t.parse().ok()?;
        Some(if int { V::Int(f) } else { V::Num(f) })
    }
    fn hex4(&mut self) -> Option<u32> {
        if self.i + 4 > self.b.len() {
            return None;
        }
        let t = std::str::from_utf8(&self.b[self.i..self.i + 4]).ok()?;
        if !t.bytes().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }
        self.i += 4;
        u32::from_str_radix(t, 16).ok()
    }
    fn string(&mut self) -> Option<String> {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = *self.b.get(self.i)?;
            self.i += 1;
            match c {
                b'"' => return String::from_utf8(out).ok(),
                b'\\' => {
                    let e = *self.b.get(self.i)?;
                    self.i += 1;
                    let ch = match e {
                        b'"' => '"',
                        b'\\' => '\\',
                        b'/' => '/',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        b'n' => '\n',
                        b'r' => '\r',
                        b't' => '\t',
                        b'u' => {
                            let mut u = self.hex4()?;
                            if (0xD800..0xDC00).contains(&u) {
                                if self.b.get(self.i) == Some(&b'\\')
                                    && self.b.get(self.i + 1) == Some(&b'u')
                                {
                                    self.i += 2;
                                    let lo = self.hex4()?;
                                    if !(0xDC00..0xE000).contains(&lo) {
                                        return None;
                                    }
                                    u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00);
                                } else {
                                    return None;
                                }
                            } else if (0xDC00..0xE000).contains(&u) {
                                return None;
                            }
                            char::from_u32(u)?
                        }
                        _ => return None,
                    };
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
                0..=0x1f => return None,
                _ => out.push(c),
            }
        }
    }
}

fn get<'a>(o: &'a [(String, V)], k: &str) -> Option<&'a V> {
    o.iter().find(|(n, _)| n == k).map(|(_, v)| v)
}

fn process(v: &V) -> Option<BTreeMap<String, f64>> {
    let mut m: BTreeMap<String, f64> = BTreeMap::new();
    let orders = match v {
        V::Arr(a) => a,
        _ => return None,
    };
    for o in orders {
        let o = match o {
            V::Obj(o) => o,
            _ => return None,
        };
        if !matches!(get(o, "id")?, V::Int(_)) {
            return None;
        }
        let cust = match get(o, "customer")? {
            V::Str(s) => s.clone(),
            _ => return None,
        };
        match get(o, "note") {
            None | Some(V::Str(_)) => {}
            _ => return None,
        }
        let items = match get(o, "items")? {
            V::Arr(a) => a,
            _ => return None,
        };
        let e = m.entry(cust).or_insert(0.0);
        for it in items {
            let it = match it {
                V::Obj(x) => x,
                _ => return None,
            };
            if !matches!(get(it, "sku")?, V::Str(_)) {
                return None;
            }
            let q = match get(it, "qty")? {
                V::Int(q) => *q,
                _ => return None,
            };
            let p = match get(it, "price")? {
                V::Int(p) | V::Num(p) => *p,
                _ => return None,
            };
            *e += q * p;
        }
    }
    Some(m)
}

fn main() {
    let mut buf = Vec::new();
    let _ = std::io::stdin().read_to_end(&mut buf);
    let mut p = P { b: &buf, i: 0 };
    let res = (|| {
        let v = p.value(0)?;
        p.ws();
        if p.i != p.b.len() {
            return None;
        }
        process(&v)
    })();
    match res {
        Some(m) => {
            for (k, v) in m {
                println!("{} {:.2}", k, v + 0.0);
            }
        }
        None => {
            println!("invalid input");
            std::process::exit(1);
        }
    }
    let _ = V::Null;
}

